<?php
$id = filter_var($_GET['id'] ?? null, FILTER_VALIDATE_INT);
if ($id && $id > 0) {
    $r = ClientApi::data($api->request('GET', 'api/reservations/' . $id));
    ?><section class="panel"><a class="text-link" href="?page=reservations">← Toutes mes réservations</a><h2 class="section-title" style="margin-top:18px">Réservation <?= client_h($r['reference'] ?? '') ?> <?= client_status_badge((string)($r['statut'] ?? '')) ?></h2><div class="grid stats"><div><div class="stat-label">Itinéraire</div><b><?= client_h($r['libelle_snapshot'] ?? '—') ?></b></div><div><div class="stat-label">Date de départ</div><b><?= client_h(client_format_date($r['depart_at'] ?? null)) ?></b></div><div><div class="stat-label">Participants</div><b><?= (int)($r['quantite'] ?? 1) ?></b></div><div><div class="stat-label">Montant estimé</div><b><?= client_money($r['montant_total'] ?? null, $r['devise'] ?? null) ?></b></div></div><p class="row-meta">Demande créée le <?= client_h(client_format_date($r['created_at'] ?? null)) ?>. La disponibilité et les détails sont confirmés par le transporteur.</p><?php if (($r['statut'] ?? '') === 'demande'): ?><form method="post" data-confirm="Annuler cette demande de réservation ?"><?= client_csrf_field() ?><input type="hidden" name="action" value="reservation_cancel"><input type="hidden" name="id" value="<?= (int)$r['id'] ?>"><button class="btn btn-outline" type="submit">Annuler la demande</button></form><?php endif; ?></section><?php
} else {
    $rows = ClientApi::data($api->request('GET', 'api/reservations'));
    ?><section class="panel"><h2 class="section-title">Toutes vos réservations</h2><?php if (!$rows): ?><div class="empty"><div class="empty-icon">▤</div><h3>Aucune réservation pour le moment</h3><p>Vos demandes de transport apparaîtront dès leur enregistrement.</p><a class="btn" href="?page=help">Comment réserver ?</a></div><?php else: ?><div class="table-wrap"><table class="data-table"><thead><tr><th>Référence</th><th>Itinéraire</th><th>Date de demande</th><th>Montant</th><th>Statut</th><th></th></tr></thead><tbody><?php foreach ($rows as $r): ?><tr><td><?= client_h($r['reference'] ?? '') ?></td><td><?= client_h($r['libelle_snapshot'] ?? '—') ?></td><td><?= client_h(client_format_date($r['created_at'] ?? null)) ?></td><td><?= client_money($r['montant_total'] ?? null,$r['devise'] ?? null) ?></td><td><?= client_status_badge((string)($r['statut'] ?? '')) ?></td><td><a class="text-link" href="?page=reservations&amp;id=<?= (int)$r['id'] ?>">Détails</a></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section><?php
}
